// Deterministic availability check
const hospitalRaw = $node['HTTP - Hospital Resources'].json;
// many HTTP nodes return the response under .json or .body; normalize
const hospital = (hospitalRaw && hospitalRaw.json) ? hospitalRaw.json : hospitalRaw;
const resources = hospital.resources || hospital;
// Retrieve extracted requirements from earlier node
const extracted = $node['Validate Extract'].json.extracted;
const required = extracted.resource_requirements || [];
let missing = [];
for(const req of required){
  const t = req.type;
  const subtype = req.subtype || '';
  const needed = req.count || 0;
  if(t === 'bed'){
    const bed = (resources.beds && (resources.beds[subtype] || resources.beds[subtype.toLowerCase()])) || null;
    const avail = bed ? (bed.available || 0) : 0;
    if(avail < needed) missing.push({ item:`bed:${subtype}`, needed, available: avail});
  } else if(t === 'blood_units'){
    const avail = (resources.blood_units && (resources.blood_units[subtype] || 0)) || 0;
    if(avail < needed) missing.push({ item:`blood:${subtype}`, needed, available: avail});
  } else if(t === 'specialist'){
    const doctors = (resources.doctors || []).filter(d => (d.specialization||'').toLowerCase().includes(subtype.toLowerCase()));
    const oncall = doctors.filter(d => d.on_call).length;
    if(oncall < needed) missing.push({ item:`specialist:${subtype}`, needed, available: oncall});
  } else if(t === 'equipment'){
    const has = (resources.equipment || []).includes(subtype);
    if(!has) missing.push({ item:`equipment:${subtype}`, needed: 1, available: 0});
  } else {
    missing.push({ item:`unknown:${subtype}`, needed, available: 0});
  }
}
const deterministic_ok = missing.length === 0;
return [{ json: { hospital: hospital, deterministic_ok, missing_items: missing, extracted: extracted } }];

