// Validate Schema B (Hospital Assessment)
function validateAssessment(obj){
  if(!obj || typeof obj !== 'object') return 'Not an object';
  if(typeof obj.accept !== 'boolean') return 'accept missing';
  if(!Array.isArray(obj.missing_items)) return 'missing_items not array';
  if(!Number.isInteger(obj.prep_eta_minutes) || obj.prep_eta_minutes < 0) return 'prep_eta_minutes invalid';
  if(!Number.isInteger(obj.payment_estimate_cents) || obj.payment_estimate_cents < 0) return 'payment_estimate_cents invalid';
  if(typeof obj.confidence !== 'number' || obj.confidence < 0 || obj.confidence > 1) return 'confidence invalid';
  if(typeof obj.notes !== 'string') return 'notes missing';
  for(const m of obj.missing_items){
    if(typeof m.item !== 'string') return 'missing_items.item missing';
    if(!Number.isInteger(m.needed) || m.needed < 0) return 'missing_items.needed invalid';
    if(!Number.isInteger(m.available) || m.available < 0) return 'missing_items.available invalid';
  }
  return null;
}
const payload = items[0].json;
const error = validateAssessment(payload);
if(error) throw new Error('Schema B validation failed: '+error);
return [{ json: payload }];

// Decide final acceptance combining deterministic check and LLM assessment
const llm = $node['Validate Assessment'].json;
const det = $node['Function - Deterministic Check'].json;
// Policy: accept if deterministic_ok OR (llm.accept AND llm.confidence >= 0.9)
const finalAccept = det.deterministic_ok || (llm.accept === true && llm.confidence >= 0.9);
const emergency = $node['Validate Extract'].json.original;
